const assert = require('node:assert/strict');
const fs = require('node:fs');
const vm = require('node:vm');
const source = fs.readFileSync('deep clone', 'utf8');
const deepCloneObj = vm.runInNewContext(source + '\ndeepCloneObj', { Map, Set });
const original = { nested: { value: 4 }, values: [1, { value: 2 }] };
const clone = deepCloneObj(original);
assert.deepEqual(clone, original);
assert.notEqual(clone, original);
assert.notEqual(clone.nested, original.nested);
assert.notEqual(clone.values, original.values);
assert.notEqual(clone.values[1], original.values[1]);
const map = new Map([['x', { value: 1 }]]);
const mapClone = deepCloneObj(map);
assert.deepEqual(mapClone, map);
assert.notEqual(mapClone.get('x'), map.get('x'));
const item = { value: 3 };
const setClone = deepCloneObj(new Set([item]));
assert.deepEqual([...setClone], [item]);
assert.notEqual([...setClone][0], item);
for (const value of [null, undefined, false, 0, 'hello']) assert.equal(deepCloneObj(value), value);
console.log('PASS: deep clone objects, arrays, Maps, Sets, and primitive regressions');
